    def test_firstresult_force_result(pm: PluginManager) -> None:
        """Verify forcing a result in a wrapper."""

        class Api:
            @hookspec(firstresult=True)
            def hello(self, arg):
                "api hook 1"

        pm.add_hookspecs(Api)

        class Plugin1:
            @hookimpl
            def hello(self, arg):
                return arg + 1

        class Plugin2:
            @hookimpl
            def hello(self, arg):
                assert arg == 3
                outcome = yield
                assert outcome == 4
                return 0

        class Plugin3:
            @hookimpl
            def hello(self, arg):
                return None

        pm.register(Plugin1())
        pm.register(Plugin2())  # wrapper
        pm.register(Plugin3())  # ignored since returns None
        res = pm.hook.hello(arg=3)
